import { Project } from '../../src'

describe('Resolvable shapes', () => {
    test('Identifiers and property access in a template expression', async () => {
        const shapes = await new Project()
            .addFile({
                path: 'test.now.ts',
                content: `
const foo = 'one'
const bar = { one: 'two' }
const baz = { one: { two: 'three' } }

export const text = \`foo: \${foo}, bar: \${bar.one}, baz: \${baz.one.two}\``,
            })
            .getShapes()

        const text = shapes
            .find((s) => s.ifIdentifier()?.getName() === 'text')
            ?.asIdentifier()
            .resolve()

        expect(text).toBeDefined()
        expect(text.getCode()).toBe(`\`foo: \${foo}, bar: \${bar.one}, baz: \${baz.one.two}\``)
        expect(text.getValue()).toBe('foo: one, bar: two, baz: three')
    })
})
